<script setup lang="ts">import {ref,computed,reactive} from 'vue';import PageHeader from '@/components/shared/PageHeader.vue';import BaseBadge from '@/components/base/BaseBadge.vue';import {EquipmentService,ReportService} from '@/services';import {useAppStore} from '@/stores/app';import type {Equipment} from '@/types';import {Search,Plus,Download,Printer,X} from 'lucide-vue-next';const items=ref(EquipmentService.list()),query=ref(''),category=ref('Todas'),status=ref('Todos'),modal=ref(false),app=useAppStore();const filtered=computed(()=>items.value.filter(e=>(!query.value||e.code.toLowerCase().includes(query.value.toLowerCase()))&&(category.value==='Todas'||e.category===category.value)&&(status.value==='Todos'||e.status===status.value)));const form=reactive<Equipment>({id:0,code:'',asset:'',name:'',category:'Computador',brand:'',model:'',serial:'',department:'',location:'',owner:'',ip:'',os:'',purchasedAt:'',warranty:'',status:'Disponível',tickets:0,lastMaintenance:'Nunca'});function save(){if(!form.code||!form.name){app.toast('Dados incompletos','Informe código e nome.','error');return}form.id=Math.max(0,...items.value.map(x=>x.id))+1;items.value.unshift({...form});EquipmentService.save(items.value);modal.value=false;app.toast('Equipamento cadastrado',`${form.code} foi adicionado ao inventário.`)}function exportPdf(){ReportService.exportPdf('Equipamentos',['Código','Nome','Categoria','Setor','Status'],filtered.value.map(e=>[e.code,e.name,e.category,e.department,e.status]));app.toast('Relatório gerado','O PDF do inventário foi baixado.')}</script>
<template><PageHeader title="Equipamentos" description="Inventário e ciclo de vida dos ativos de tecnologia"><button class="btn btn-secondary" @click="exportPdf"><Download class="size-4"/>Exportar PDF</button><button class="btn btn-primary" @click="modal=true"><Plus class="size-4"/>Novo equipamento</button></PageHeader><div class="mb-3 grid grid-cols-4 gap-3"><div v-for="m in [['Total de ativos',items.length],['Em uso',items.filter(x=>x.status==='Em uso').length],['Em manutenção',items.filter(x=>x.status.includes('manutenção')).length],['Garantia a vencer',5]]" :key="String(m[0])" class="card p-3"><div class="text-xs text-slate-500">{{m[0]}}</div><b class="mt-1 block text-xl">{{m[1]}}</b></div></div><div class="card overflow-hidden"><div class="flex gap-2 border-b p-3 dark:border-slate-700"><div class="relative w-64"><Search class="absolute left-3 top-2.5 size-4 text-slate-400"/><input v-model="query" class="field pl-9" placeholder="Código"/></div><select v-model="category" class="field w-44"><option>Todas</option><option>Computador</option><option>Notebook</option><option>Impressora</option><option>Servidor</option><option>Switch</option></select><select v-model="status" class="field w-44"><option>Todos</option><option>Em uso</option><option>Disponível</option><option>Em manutenção</option><option>Aguardando peça</option><option>Danificado</option></select><button class="btn btn-secondary ml-auto" @click="app.toast('Etiquetas geradas','Etiquetas selecionadas enviadas para impressão.')"><Printer class="size-4"/>Imprimir etiquetas</button></div><table class="w-full text-left text-xs"><thead class="table-head"><tr><th class="px-4 py-3">Código / Patrimônio</th><th>Equipamento</th><th>Categoria</th><th>Setor / Local</th><th>Responsável</th><th>Rede</th><th>Status</th><th>Chamados</th></tr></thead><tbody><tr v-for="e in filtered" :key="e.id" class="border-t border-slate-100 hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-700/30"><td class="px-4 py-3"><router-link :to="`/equipamentos/${e.id}`" class="font-mono font-semibold text-blue-600">{{e.code}}</router-link><div class="text-[10px] text-slate-400">{{e.asset}}</div></td><td><router-link :to="`/equipamentos/${e.id}`" class="font-semibold">{{e.name}}</router-link><div class="text-[10px] text-slate-500">{{e.brand}} {{e.model}}</div></td><td>{{e.category}}</td><td>{{e.department}}<div class="text-[10px] text-slate-400">{{e.location}}</div></td><td>{{e.owner}}</td><td class="font-mono">{{e.ip}}<div class="text-[10px] text-slate-400">{{e.os}}</div></td><td><BaseBadge :label="e.status"/></td><td>{{e.tickets}}</td></tr></tbody></table></div><div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45" @mousedown.self="modal=false"><form class="card max-h-[90vh] w-[820px] overflow-auto shadow-2xl" @submit.prevent="save"><div class="flex items-center justify-between border-b px-6 py-4 dark:border-slate-700"><div><h2 class="font-bold">Novo equipamento</h2><p class="text-xs text-slate-500">Cadastro completo do ativo</p></div><button type="button" @click="modal=false"><X class="size-5"/></button></div><div class="grid grid-cols-3 gap-4 p-6"><div><label class="label">Código *</label><input v-model="form.code" class="field"/></div><div><label class="label">Patrimônio</label><input v-model="form.asset" class="field"/></div><div><label class="label">Categoria</label><select v-model="form.category" class="field"><option>Computador</option><option>Notebook</option><option>Impressora</option><option>Servidor</option><option>Roteador</option><option>Switch</option><option>Câmera</option><option>Telefone</option><option>Nobreak</option><option>Periférico</option></select></div><div class="col-span-2"><label class="label">Nome *</label><input v-model="form.name" class="field"/></div><div><label class="label">Status</label><select v-model="form.status" class="field"><option>Disponível</option><option>Em uso</option><option>Em estoque</option><option>Emprestado</option><option>Em manutenção</option><option>Danificado</option></select></div><div><label class="label">Marca</label><input v-model="form.brand" class="field"/></div><div><label class="label">Modelo</label><input v-model="form.model" class="field"/></div><div><label class="label">Número de série</label><input v-model="form.serial" class="field"/></div><div><label class="label">Setor</label><input v-model="form.department" class="field"/></div><div><label class="label">Localização</label><input v-model="form.location" class="field"/></div><div><label class="label">Responsável</label><input v-model="form.owner" class="field"/></div><div><label class="label">IP</label><input v-model="form.ip" class="field"/></div><div><label class="label">Sistema operacional</label><input v-model="form.os" class="field"/></div><div><label class="label">Data de compra</label><input v-model="form.purchasedAt" class="field" type="date"/></div><div><label class="label">Garantia</label><input v-model="form.warranty" class="field"/></div></div><div class="flex justify-end gap-2 border-t px-6 py-4 dark:border-slate-700"><button type="button" class="btn btn-secondary" @click="modal=false">Cancelar</button><button class="btn btn-primary">Salvar equipamento</button></div></form></div></template>
